command_line:
set -eu
python - <<'PY'
import urllib.request
from collections import OrderedDict

organism = "pa14"

def fetch(url):
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "Galaxy-KEGG-mapping/1.0", "Accept": "text/plain"},
    )
    try:
        with urllib.request.urlopen(request, timeout=90) as response:
            return response.read().decode("utf-8")
    except Exception as exc:
        raise RuntimeError(f"KEGG request failed for {url}: {exc}") from exc

links = fetch(f"https://rest.kegg.jp/link/pathway/{organism}")
pathway_names = fetch(f"https://rest.kegg.jp/list/pathway/{organism}")

names = {}
for line in pathway_names.splitlines():
    fields = line.split("\t", 1)
    if len(fields) == 2:
        names[fields[0]] = fields[1]

rows = OrderedDict()
for line in links.splitlines():
    fields = line.split("\t")
    if len(fields) < 2:
        continue
    gene = fields[0].split(":", 1)[-1]
    pathway_id = fields[1]
    pathway_name = names.get(pathway_id, pathway_id)
    rows[(gene, pathway_id)] = pathway_name

if not rows:
    raise RuntimeError(f"KEGG returned no gene-to-pathway rows for {organism}")

with open("kegg_pa14_mapping.tsv", "w", encoding="utf-8", newline="") as handle:
    handle.write("gene\tpathway_id\tpathway_name\n")
    for (gene, pathway_id), pathway_name in rows.items():
        handle.write(f"{gene}\t{pathway_id}\t{pathway_name}\n")

print(f"wrote {len(rows)} unique {organism} gene-to-pathway mappings")
PY
